const items = $input.all();
const results = [];
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

for (const item of items) {
  const payload = item.json.body || item.json;
  const data = payload.data || payload;

  const leadName = data.name || data.lead_name || payload.name || 'Valued Prospect';
  const rawPhone = String(data.phone || payload.to || payload.phone || '').trim();
  const studioName = data.studio_name || payload.studio_name || 'Wellness Studio';
  const leadId = data.lead_id || data.id || payload.subjectRef || `lead_${Date.now()}`;
  const eventId = payload.eventId || payload.event_id || `evt_${Date.now()}`;
  const tenantId = payload.tenantId || payload.tenant_id || 'default-tenant';
  const correlationId = payload.correlationId || payload.correlation_id || `corr_${Date.now()}`;

  const cleanDigits = rawPhone.replace(/[^0-9]/g, '');
  const isUuid = uuidPattern.test(rawPhone);
  const isValidPhone = !isUuid && cleanDigits.length >= 10 && cleanDigits.length <= 15;
  const formattedPhone = cleanDigits.length >= 10 ? (rawPhone.startsWith('+') ? rawPhone.replace(/[^0-9+]/g, '') : `+${cleanDigits}`) : '';

  results.push({
    json: {
      to: formattedPhone || rawPhone,
      phone: formattedPhone || rawPhone,
      rawRecipient: rawPhone,
      isValidPhone,
      isDirectDelivery: true,
      source: 'domain_workflow',
      workflow_name: 'lead-confirmation',
      template: 'lead-registration-confirmation',
      template_name: 'lead-registration-confirmation',
      tenantId,
      eventId,
      correlationId,
      idempotencyKey: `lead_confirm_${leadId}`,
      data: {
        lead_name: leadName,
        studio_name: studioName,
        lead_id: leadId
      }
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  results.push({
    json: {
      alertType: 'notification_failure',
      severity: 'high',
      workflow_name: 'lead-confirmation',
      eventId: d.eventId,
      recipient: d.rawRecipient || d.to,
      template: d.template,
      error_code: 'INVALID_LEAD_PHONE',
      error_message: `Lead phone '${d.rawRecipient}' is missing or invalid. Expected E.164 phone format.`,
      tenantId: d.tenantId,
      correlationId: d.correlationId,
      timestamp: new Date().toISOString()
    }
  });
}

return results;

